// Turns the hero's floorplan drawing (docs/design/hero-2026-09-19/plan/plan.svg,
// itself generated by gen.js there) into src/landing/heroPlanSvg.ts: one SVG
// string per locale, ready to inline.
//
//   node scripts/landing/build-hero-plan.mjs
//
// What it does to the drawing, and why:
//   - Strips <title> and the per-<text> font-family. The backdrop is decorative
//     (aria-hidden), and the labels take the page's own mono stack from CSS so
//     they render in the loaded IBM Plex Mono / Rubik, not a system fallback.
//   - Swaps each room label to its locale's `data-*` text, then drops the data
//     attributes so the shipped markup carries one language, not two.
//   - Hebrew: mirrors the whole drawing about its centre (the plan leans in from
//     the reading side, so in RTL it sits on the left), then re-flips every
//     <text> about its own anchor so the words still read. Done here, as geometry,
//     rather than with CSS transforms: a CSS `transform` on a <text> REPLACES its
//     `transform` attribute, which silently un-rotates the vertical dimensions.

import { readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)), "..", "..");
const SRC = join(root, "docs/design/hero-2026-09-19/plan/plan.svg");
const OUT = join(root, "src/landing/heroPlanSvg.ts");

const raw = readFileSync(SRC, "utf8");
const vb = raw.match(/viewBox="([^"]+)"/)[1].split(/\s+/).map(Number);
const cx = vb[0] + vb[2] / 2; // mirror axis
const inner = raw
  .replace(/^[\s\S]*?<svg[^>]*>/, "")
  .replace(/<\/svg>\s*$/, "")
  .replace(/<title>[\s\S]*?<\/title>\s*/, "")
  .replace(/\s*font-family="[^"]*"/g, "");

const unesc = (s) => s.replace(/&quot;/g, '"').replace(/&amp;/g, "&");
const esc = (s) => s.replace(/&/g, "&amp;").replace(/</g, "&lt;");

function localise(body, locale) {
  return body.replace(/<text([^>]*)>([^<]*)<\/text>/g, (_, attrs, text) => {
    const m = attrs.match(new RegExp(`data-${locale}="([^"]*)"`));
    const label = m ? esc(unesc(m[1])) : text;
    return `<text${attrs.replace(/\s*data-(en|he)="[^"]*"/g, "")}>${label}</text>`;
  });
}

function unmirrorText(body) {
  return body.replace(/<text([^>]*)>/g, (_, attrs) => {
    const x = Number((attrs.match(/\sx="([^"]*)"/) || [])[1] || 0);
    const tr = (attrs.match(/\stransform="([^"]*)"/) || [])[1];
    const tx = tr ? Number((tr.match(/translate\(\s*([-\d.]+)/) || [])[1] || 0) : 0;
    const pivot = x + tx;
    const flip = `translate(${pivot} 0) scale(-1 1) translate(${-pivot} 0)`;
    let a = attrs.replace(/\stransform="[^"]*"/, "");
    // Keep start/end anchored text growing away from the edge it was aligned to.
    a = a.replace(/text-anchor="(start|end)"/, (_, v) => `text-anchor="${v === "start" ? "end" : "start"}"`);
    return `<text${a} transform="${flip}${tr ? " " + tr : ""}">`;
  });
}

const open = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="${vb.join(" ")}" aria-hidden="true" focusable="false">`;
const en = `${open}${localise(inner, "en")}</svg>`;
const he = `${open}<g transform="translate(${2 * cx} 0) scale(-1 1)">${unmirrorText(localise(inner, "he"))}</g></svg>`;

writeFileSync(
  OUT,
  `// GENERATED by scripts/landing/build-hero-plan.mjs from
// docs/design/hero-2026-09-19/plan/plan.svg. Do not edit by hand.
// Our own drawing, generated in code: no third-party licence.

export const HERO_PLAN_SVG = {
  en: ${JSON.stringify(en.replace(/\n+/g, ""))},
  he: ${JSON.stringify(he.replace(/\n+/g, ""))},
} as const;
`,
);
console.log(`wrote ${OUT} (en ${en.length} B, he ${he.length} B)`);
